-- ============================================
-- LUMA — Thème 14 (Road trip US) : 3 scénarios COURTS x4
-- ============================================


update scenarios set content = '{"characters": {"agent": "l''agent de location"}, "start_node": "n1", "nodes": {"n1": {"speaker": "agent", "text": "Welcome! I see you booked the compact SUV. Would you like to add insurance coverage?", "text_fr": "Bienvenue ! Je vois que vous avez réservé le SUV compact. Vous voulez ajouter une assurance ?", "choices": [{"text": "What''s included in the basic rental already?", "text_fr": "Qu''est-ce qui est déjà inclus dans la location de base ?", "next": "n2"}, {"text": "Yes, I''d like full coverage, better safe than sorry.", "text_fr": "Oui, j''aimerais une couverture complète, mieux vaut prévenir que guérir.", "next": "n2b"}]}, "n2": {"speaker": "agent", "text": "Basic liability is included, but it doesn''t cover damage to the vehicle itself.", "text_fr": "La responsabilité de base est incluse, mais ça couvre pas les dommages au véhicule lui-même.", "choices": [{"text": "I''ll add the collision coverage then, just to be safe.", "text_fr": "Je vais ajouter la couverture collision alors, juste par sécurité.", "next": "n3"}, {"text": "I think I''ll stick with the basic coverage for now.", "text_fr": "Je pense que je vais rester sur la couverture de base pour l''instant.", "next": "n3b"}]}, "n2b": {"speaker": "agent", "text": "Great choice, full coverage gives you complete peace of mind on the road.", "text_fr": "Excellent choix, la couverture complète vous donne une tranquillité d''esprit complète sur la route.", "choices": [{"text": "Exactly what I was hoping for. What''s the total cost with that added?", "text_fr": "Exactement ce que j''espérais. C''est quoi le coût total avec ça ajouté ?", "next": "n3"}]}, "n3": {"speaker": "agent", "text": "With collision coverage, your total comes to $65 per day.", "text_fr": "Avec la couverture collision, votre total est de 65$ par jour.", "choices": [{"text": "That works for me, let''s finalize the paperwork.", "text_fr": "Ça me convient, finalisons les papiers.", "next": "n4"}]}, "n3b": {"speaker": "agent", "text": "Understood, just note you''d be responsible for any vehicle damage costs.", "text_fr": "Compris, notez juste que vous seriez responsable de tous frais de dommages au véhicule.", "choices": [{"text": "That''s fine, I''ll drive carefully. Let''s proceed with the basic plan.", "text_fr": "C''est bon, je vais conduire prudemment. Continuons avec le plan de base.", "next": "n4"}]}, "n4": {"speaker": "agent", "text": "Perfect, please sign here, and I''ll get your keys ready.", "text_fr": "Parfait, signez ici s''il vous plaît, et je vais préparer vos clés.", "choices": [{"text": "(Sign the contract carefully after reading it.)", "text_fr": "(Signe le contrat avec attention après l''avoir lu.)", "next": "n5"}]}, "n5": {"speaker": "agent", "text": "All set! Here are your keys, and the car''s parked in spot 12.", "text_fr": "Tout est prêt ! Voici vos clés, et la voiture est garée à l''emplacement 12.", "choices": [{"text": "Thank you so much, I''m excited for this road trip!", "text_fr": "Merci beaucoup, j''ai hâte pour ce road trip !", "next": "end_rented"}]}, "end_rented": {"speaker": "agent", "text": "Have an amazing trip, safe travels out there!", "text_fr": "Passez un voyage incroyable, bonne route !", "end": true, "ending_label": "Voiture louée, contrat bien compris 🚗📋"}}}'::jsonb, is_playable = true
where title = 'Louer une voiture et comprendre le contrat'
  and theme_id = (select id from scenario_themes where position = 14 and language_id = (select id from languages where code = 'en'));


update scenarios set content = '{"characters": {"waitress": "la serveuse"}, "start_node": "n1", "nodes": {"n1": {"speaker": "waitress", "text": "Hey hon, what can I get you? Coffee to start?", "text_fr": "Salut chéri, je te sers quoi ? Un café pour commencer ?", "choices": [{"text": "Yes please, and I''ll have a look at the menu.", "text_fr": "Oui s''il vous plaît, et je vais jeter un œil au menu.", "next": "n2"}, {"text": "Actually, could I get an iced tea instead?", "text_fr": "En fait, je pourrais avoir un thé glacé plutôt ?", "next": "n2b"}]}, "n2": {"speaker": "waitress", "text": "Sure thing, coffee''s coming right up. Let me know when you''re ready to order.", "text_fr": "Bien sûr, le café arrive tout de suite. Dites-moi quand vous êtes prêt à commander.", "choices": [{"text": "I think I''ll have the classic burger and fries.", "text_fr": "Je pense que je vais prendre le burger classique et des frites.", "next": "n3"}]}, "n2b": {"speaker": "waitress", "text": "You got it, sweetie. Ready to order some food too?", "text_fr": "C''est noté, chéri. Prêt à commander de la nourriture aussi ?", "choices": [{"text": "Yes, I''ll have the classic burger and fries.", "text_fr": "Oui, je vais prendre le burger classique et des frites.", "next": "n3"}]}, "n3": {"speaker": "waitress", "text": "Great choice! How would you like that burger cooked?", "text_fr": "Excellent choix ! Vous voulez votre burger cuit comment ?", "choices": [{"text": "Medium, please.", "text_fr": "À point, s''il vous plaît.", "next": "n4"}, {"text": "Well done, if that''s possible.", "text_fr": "Bien cuit, si possible.", "next": "n4"}]}, "n4": {"speaker": "waitress", "text": "You got it. Any sides besides the fries, or that''s all?", "text_fr": "C''est noté. Des accompagnements en plus des frites, ou c''est tout ?", "choices": [{"text": "That''s all, thank you.", "text_fr": "C''est tout, merci.", "next": "n5"}, {"text": "Actually, could I add a milkshake too?", "text_fr": "En fait, je pourrais ajouter un milkshake aussi ?", "next": "n5"}]}, "n5": {"speaker": "waitress", "text": "Perfect, I''ll get that started for you right away.", "text_fr": "Parfait, je lance ça pour vous tout de suite.", "choices": [{"text": "Thank you so much!", "text_fr": "Merci beaucoup !", "next": "end_ordered"}]}, "end_ordered": {"speaker": "waitress", "text": "You''re welcome, hon. It''ll be right out!", "text_fr": "Je vous en prie, chéri. Ça arrive tout de suite !", "end": true, "ending_label": "Commande passée dans un vrai diner américain 🍔🇺🇸"}}}'::jsonb, is_playable = true
where title = 'Commander dans un diner américain'
  and theme_id = (select id from scenario_themes where position = 14 and language_id = (select id from languages where code = 'en'));
